import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import type {
  ContentViewConfig,
  CornerViewConfig,
  RootViewConfig,
  ScrollbarViewConfig,
  ThumbViewConfig,
  ViewConfig,
  ViewportViewConfig,
} from "../scroll-area";
import {
  shadcnScrollAreaContentClassName,
  shadcnScrollAreaCornerClassName,
  shadcnScrollAreaFadeClassName,
  shadcnScrollAreaRootClassName,
  shadcnScrollAreaScrollbarClassName,
  shadcnScrollAreaThumbClassName,
  shadcnScrollAreaViewportClassName,
} from "./view";

export type {
  ContentViewConfig,
  CornerViewConfig,
  RootViewConfig,
  ScrollAreaStyle,
  ScrollbarViewConfig,
  ThumbViewConfig,
  ViewConfig,
  ViewportViewConfig,
} from "../scroll-area";

export {
  shadcnScrollAreaContentClassName,
  shadcnScrollAreaCornerClassName,
  shadcnScrollAreaFadeClassName,
  shadcnScrollAreaRootClassName,
  shadcnScrollAreaScrollbarClassName,
  shadcnScrollAreaThumbClassName,
  shadcnScrollAreaViewportClassName,
} from "./view";

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  config: Pick<RootViewConfig, "hasOverflowX" | "hasOverflowY" | "isScrolling">
) => [
  ...(config.hasOverflowX === true
    ? [h.DataAttribute("has-overflow-x", "")]
    : []),
  ...(config.hasOverflowY === true
    ? [h.DataAttribute("has-overflow-y", "")]
    : []),
  ...(config.isScrolling === true ? [h.DataAttribute("scrolling", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  className,
  style,
  hasOverflowX,
  hasOverflowY,
  isScrolling,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, { hasOverflowX, hasOverflowY, isScrolling }),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaRootClassName, className)),
    ],
    children
  );
};

export const viewportView = <ParentMessage>({
  children,
  className,
  style,
  ariaLabel,
}: ViewportViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("tabindex", "0"),
      ...(ariaLabel === undefined
        ? []
        : [h.Attribute("role", "region"), h.AriaLabel(ariaLabel)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaViewportClassName, className)),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  className,
  style,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaContentClassName, className)),
    ],
    children
  );
};

export const scrollbarView = <ParentMessage>({
  children,
  className,
  style,
}: ScrollbarViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaScrollbarClassName, className)),
    ],
    children
  );
};

export const thumbView = <ParentMessage>({
  className,
  style,
}: ThumbViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaThumbClassName, className)),
    ],
    []
  );
};

export const cornerView = <ParentMessage>({
  className,
  style,
}: CornerViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(shadcnScrollAreaCornerClassName, className)),
    ],
    []
  );
};

export const view = <ParentMessage>({
  children,
  ariaLabel,
  hasFade = false,
  className,
  style,
  viewportClassName,
  viewportStyle,
  contentClassName,
  contentStyle,
}: ViewConfig): Html =>
  rootView<ParentMessage>({
    className,
    style,
    hasOverflowY: true,
    children: [
      viewportView<ParentMessage>({
        ariaLabel,
        className: hasFade
          ? classNames(shadcnScrollAreaFadeClassName, viewportClassName)
          : viewportClassName,
        style: viewportStyle,
        children: [
          contentView<ParentMessage>({
            className: contentClassName,
            style: contentStyle,
            children,
          }),
        ],
      }),
      scrollbarView<ParentMessage>({
        children: [thumbView<ParentMessage>()],
      }),
    ],
  });

export const shadcnScrollAreaRootClassName =
  "relative h-48 w-80 max-w-full overflow-hidden rounded-md border border-gray-200 bg-white";
export const shadcnScrollAreaViewportClassName =
  "h-full w-full overflow-auto overscroll-contain rounded-[inherit] p-4 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden";
export const shadcnScrollAreaContentClassName =
  "space-y-3 text-sm leading-6 text-gray-700";
export const shadcnScrollAreaScrollbarClassName =
  "pointer-events-none absolute inset-y-0 right-0 flex w-2.5 touch-none select-none border-l border-l-transparent p-px transition-colors";
export const shadcnScrollAreaThumbClassName =
  "relative flex-1 rounded-full bg-gray-300";
export const shadcnScrollAreaCornerClassName =
  "pointer-events-none absolute bottom-0 right-0 h-2.5 w-2.5 bg-white";
export const shadcnScrollAreaFadeClassName =
  "[mask-image:linear-gradient(to_bottom,transparent,black_1rem,black_calc(100%-1rem),transparent)]";

import { describe, expect, test } from "vitest";

import { scrollAreaScrollbarClassName } from "../scroll-area";
import * as ScrollArea from "./index";

describe("shadcn Scroll Area registry view", () => {
  test("exports the Foldkit Scroll Area view contract", () => {
    expect(ScrollArea.rootView).toBeTypeOf("function");
    expect(ScrollArea.viewportView).toBeTypeOf("function");
    expect(ScrollArea.view).toBeTypeOf("function");
    expect(ScrollArea.shadcnScrollAreaRootClassName).toContain("overflow");
  });

  test("uses shadcn indicator styling instead of the base scrollbar lane", () => {
    expect(ScrollArea.shadcnScrollAreaViewportClassName).toContain(
      "[scrollbar-width:none]"
    );
    expect(ScrollArea.shadcnScrollAreaScrollbarClassName).toContain("flex");
    expect(ScrollArea.shadcnScrollAreaThumbClassName).toContain("flex-1");
    expect(ScrollArea.shadcnScrollAreaScrollbarClassName).not.toEqual(
      scrollAreaScrollbarClassName
    );
  });
});
